QString treeIconsDir()
{
    static bool resolved = false;
    static QString cached;
    if (resolved)
        return cached;
    resolved = true;
    static const QString kResourceDir = QStringLiteral(":/icons/tree");
    if (QDir(kResourceDir).exists()) {
        cached = kResourceDir;
        return cached;
    }
    const QString src = QStringLiteral(FORKMESH_SOURCE_DIR);
    if (!src.isEmpty()) {
        const QString candidate = QDir(src).absoluteFilePath(QStringLiteral("icons"));
        if (QDir(candidate).exists()) {
            cached = QDir(candidate).absolutePath();
            return cached;
        }
    }
    const QString beside =
        QCoreApplication::applicationDirPath() + QStringLiteral("/icons");
    if (QDir(beside).exists())
        cached = beside;
    return cached;
}

QString fileTypeIconMarkup(const QString &fileName, int size)
{
    const QString name = fileTypeIconName(fileName.toLower());
    const qreal dpr = iconDevicePixelRatio();
    const QString key = name + QLatin1Char('|') + QString::number(size) +
                        QLatin1Char('|') + QString::number(dpr);
    static QHash<QString, QString> cache;
    const auto cached = cache.constFind(key);
    if (cached != cache.constEnd())
        return *cached;

    const QString dir = treeIconsDir();
    QString path = dir.isEmpty() ? QString()
                                 : dir + QLatin1Char('/') + name +
                                       QStringLiteral(".svg");
    if (!path.isEmpty() && !QFileInfo::exists(path))
        path = dir + QStringLiteral("/default_file.svg");
    QSvgRenderer renderer(path);
    if (path.isEmpty() || !renderer.isValid())
        return *cache.insert(key, QString());

    QPixmap pixmap = crispIconPixmap(size, dpr);
    QPainter painter(&pixmap);
    painter.setRenderHint(QPainter::Antialiasing);
    renderer.render(&painter, QRectF(0, 0, size, size));
    painter.end();
    QByteArray png;
    QBuffer buffer(&png);
    buffer.open(QIODevice::WriteOnly);
    pixmap.save(&buffer, "PNG");
    return *cache.insert(
        key, QStringLiteral("<img src='data:image/png;base64,%1' width='%2' "
                            "height='%2'>")
                 .arg(QString::fromLatin1(png.toBase64()))
                 .arg(size));
}

