QElapsedTimer &keepAliveClock()
{
    static QElapsedTimer c;
    if (!c.isValid())
        c.start();
    return c;
}

void pumpKeepAlive()
{
    g_lastKeepAlivePumpMs = keepAliveClock().elapsed();
    const KeepAlivePumpScope pumping;
    QCoreApplication::processEvents(responsiveWaitEventFlags(), 12);
}

QString gitPathspecCrumbName(const QString &pathspec)
{
    QString path = pathspec;
    if (path.startsWith(QLatin1String(":("))) {
        const int close = path.indexOf(QLatin1Char(')'));
        if (close > 0)
            path = path.mid(close + 1);
    } else if (path.startsWith(QLatin1String(":!")) ||
               path.startsWith(QLatin1String(":^"))) {
        path = path.mid(2);
    }
    const int slash = path.lastIndexOf(QLatin1Char('/'));
    return slash < 0 ? path : path.mid(slash + 1);
}

QStringList gitRedactedConfigArgs(QStringList *args, QString *repo)
{
    QStringList config;
    while (args->size() >= 2 && args->first() == QLatin1String("-c")) {
        const QString pair = args->at(1);
        const int eq = pair.indexOf(QLatin1Char('='));
        config << QStringLiteral("-c ") +
                      (eq < 0 ? pair
                              : pair.left(eq + 1) + QString::fromUtf8("…"));
        *args = args->mid(2);
    }
    if (args->size() >= 2 && args->first() == QLatin1String("-C")) {
        if (repo)
            *repo = QFileInfo(args->at(1)).fileName();
        *args = args->mid(2);
    }
    return config;
}

QString gitArgsLine(const QString &program, const QStringList &argsIn)
{
    QStringList args = argsIn;
    QString repo;
    const QStringList config = gitRedactedConfigArgs(&args, &repo);
    QString cmd = (program + QLatin1Char(' ') +
                   (config + args).join(QLatin1Char(' ')))
                      .simplified();
    if (!repo.isEmpty())
        cmd += QStringLiteral(" (%1)").arg(repo);
    return cmd;
}

QString gitArgsCrumb(const QString &program, const QStringList &argsIn)
{
    QStringList args = argsIn;
    QString repo;
    const QStringList config = gitRedactedConfigArgs(&args, &repo);
    constexpr int kShownPaths = 5;
    QString paths;
    const int sep = args.indexOf(QLatin1String("--"));
    if (sep >= 0) {
        const QStringList pathspecs = args.mid(sep + 1);
        args = args.mid(0, sep + 1); // keep the "--" on the command
        if (pathspecs.size() > kShownPaths) {
            QStringList shown;
            for (int i = 0; i < kShownPaths; ++i)
                shown << gitPathspecCrumbName(pathspecs.at(i));
            paths = shown.join(QStringLiteral(", ")) +
                    QStringLiteral(" +%1 more")
                        .arg(pathspecs.size() - kShownPaths);
        } else {
            paths = pathspecs.join(QLatin1Char(' '));
        }
    }
    QString cmd = (program + QLatin1Char(' ') +
                   (config + args).join(QLatin1Char(' ')))
                      .simplified();
    constexpr int kMaxCommand = 80;
    if (cmd.size() > kMaxCommand)
        cmd = cmd.left(kMaxCommand - 1) + QStringLiteral("…");
    if (!paths.isEmpty()) {
        cmd += QLatin1Char(' ') + paths.simplified();
        constexpr int kMaxLine = 200; // backstop for five very long names
        if (cmd.size() > kMaxLine)
            cmd = cmd.left(kMaxLine - 1) + QStringLiteral("…");
    }
    if (!repo.isEmpty())
        cmd += QStringLiteral(" (%1)").arg(repo);
    return cmd;
}

QString gitBlockingCrumb(const QProcess &process)
{
    return gitArgsCrumb(process.program(), process.arguments());
}

QString gitProcessCommandLine(const QProcess &process)
{
    return gitArgsLine(process.program(), process.arguments());
}

QString gitTimeoutError(QProcess &process, int waitedMs)
{
    const QString command = gitProcessCommandLine(process);
    forkmesh::stopProcessGracefully(process);
    QString output = QString::fromUtf8(process.readAllStandardError()).trimmed();
    const QString stdOut =
        QString::fromUtf8(process.readAllStandardOutput()).trimmed();
    if (!stdOut.isEmpty())
        output += (output.isEmpty() ? QString() : QStringLiteral("\n")) + stdOut;
    constexpr int kMaxOutput = 4000;
    if (output.size() > kMaxOutput)
        output = output.left(kMaxOutput) + QStringLiteral("\n… (output truncated)");
    QString err = QStringLiteral("git timed out after %1s: %2")
                      .arg(waitedMs / 1000)
                      .arg(command);
    if (!output.isEmpty())
        err += QLatin1Char('\n') + output;
    return err;
}

int gitWaitTimeoutMs(const QStringList &gitArguments)
{
    static const QSet<QString> writers{
        QStringLiteral("add"),         QStringLiteral("am"),
        QStringLiteral("apply"),       QStringLiteral("checkout"),
        QStringLiteral("cherry-pick"), QStringLiteral("clean"),
        QStringLiteral("commit"),      QStringLiteral("merge"),
        QStringLiteral("mv"),          QStringLiteral("pull"),
        QStringLiteral("read-tree"),   QStringLiteral("rebase"),
        QStringLiteral("reset"),       QStringLiteral("restore"),
        QStringLiteral("revert"),      QStringLiteral("rm"),
        QStringLiteral("stash"),       QStringLiteral("switch"),
        QStringLiteral("update-index"), QStringLiteral("worktree"),
    };
    for (qsizetype i = 0; i < gitArguments.size(); ++i) {
        const QString &arg = gitArguments.at(i);
        if (arg == QLatin1String("-C") || arg == QLatin1String("-c") ||
            arg == QLatin1String("--git-dir") ||
            arg == QLatin1String("--work-tree") ||
            arg == QLatin1String("--namespace")) {
            ++i;
            continue;
        }
        if (arg.startsWith(QLatin1Char('-')))
            continue;
        return writers.contains(arg) ? kGitWriteTimeoutMs : kGitReadTimeoutMs;
    }
    return kGitReadTimeoutMs;
}

QString gitFailureDetail(const GitCaptureResult &result, const QString &command,
                         int maxChars)
{
    QString detail = result.error.simplified();
    if (detail.isEmpty())
        detail = result.failureOutput.simplified();
    if (detail.isEmpty())
        return QStringLiteral("%1 failed without saying why").arg(command);
    return detail.left(maxChars);
}

bool isTransientGitError(const QString &err)
{
    // "cannot change to '<dir>'" is git refusing to run in a directory that no
    // longer exists — a removed worktree, not contention. Retrying only re-runs a
    // read that can never succeed, so rule it out before the "no such file"
    // marker below (which is there for files racing a read inside a live tree).
    if (err.contains(QLatin1String("cannot change to"), Qt::CaseInsensitive))
        return false;
    static const char *const kMarkers[] = {
        "timed out",
        "index.lock",
        "unable to create",
        "cannot lock ref",
        "unable to stat",
        "no such file",
        "resource temporarily unavailable",
        "resource deadlock",
    };
    for (const char *marker : kMarkers)
        if (err.contains(QLatin1String(marker), Qt::CaseInsensitive))
            return true;
    return false;
}

bool isGitLockContentionError(const QString &err)
{
    return forkmesh::gitLockContentionError(err);
}

QString worktreeTabKey(const QString &absPath)
{
    return QLatin1String("worktree:") + absPath;
}

QString gitignoreRuleForPath(const QString &relPath)
{
    QString rule;
    rule.reserve(relPath.size() + 8);
    for (const QChar c : relPath) {
        if (c == QLatin1Char('*') || c == QLatin1Char('?') ||
            c == QLatin1Char('[') || c == QLatin1Char(']') ||
            c == QLatin1Char('\\'))
            rule.append(QLatin1Char('\\'));
        rule.append(c);
    }
    if (rule.endsWith(QLatin1Char(' '))) {
        rule.chop(1);
        rule.append(QLatin1String("\\ "));
    }
    return QLatin1Char('/') + rule;
}

QString branchDiffErrorHtml(const QString &branch, const QString &err,
                                   int attempts)
{
    const QString message =
        err.trimmed().isEmpty() ? QStringLiteral("git failed") : err.trimmed();
    const int split = message.indexOf(QLatin1Char('\n'));
    const QString headline = split < 0 ? message : message.left(split);
    const bool dark = qApp->palette().color(QPalette::Base).lightness() < 128;
    QString html =
        QStringLiteral("<p style='color:#f85149'><b>Could not diff %1:</b> %2</p>")
            .arg(branch.toHtmlEscaped(), headline.toHtmlEscaped());
    html += QStringLiteral("<pre style='background:%1;color:%2;padding:8px;'>%3</pre>")
                .arg(dark ? QStringLiteral("#161b22") : QStringLiteral("#f6f8fa"),
                     dark ? QStringLiteral("#c9d1d9") : QStringLiteral("#24292f"),
                     message.toHtmlEscaped());
    html +=
        QStringLiteral("<p style='color:#8b949e'>Tried %1 %2. "
                       "<a href='retry:diff' style='color:#58a6ff'>Retry</a> · "
                       "<a href='repairdiff:workspace' style='color:#58a6ff;"
                       "display:inline-block;padding:3px 7px;border:1px solid "
                       "#58a6ff;border-radius:4px;text-decoration:none'>"
                       "Fix workspace &amp; retry</a></p>")
            .arg(attempts)
            .arg(attempts == 1 ? QStringLiteral("time") : QStringLiteral("times"));
    return html;
}

QString inlinePixmapMarkup(const QPixmap &pixmap, int size)
{
    if (pixmap.isNull())
        return QString();
    QByteArray png;
    QBuffer buffer(&png);
    buffer.open(QIODevice::WriteOnly);
    pixmap.save(&buffer, "PNG");
    return QStringLiteral("<img src='data:image/png;base64,%1' width='%2' "
                          "height='%2'>")
        .arg(QString::fromLatin1(png.toBase64()))
        .arg(size);
}

QString inlinePixmapMarkup(const QPixmap &pixmap, int width, int height)
{
    if (pixmap.isNull())
        return QString();
    QByteArray png;
    QBuffer buffer(&png);
    buffer.open(QIODevice::WriteOnly);
    pixmap.save(&buffer, "PNG");
    return QStringLiteral("<img src='data:image/png;base64,%1' width='%2' "
                          "height='%3'>")
        .arg(QString::fromLatin1(png.toBase64()))
        .arg(width)
        .arg(height);
}

QString roundedCornerMarkup(int radius, int corner, const QColor &fill,
                            const QColor &border)
{
    static QHash<QString, QString> cache;
    const int scale = qMax(1, qCeil(qApp->devicePixelRatio()));
    const QString key =
        QStringLiteral("%1/%2/%3/%4/%5")
            .arg(radius)
            .arg(corner)
            .arg(fill.name(QColor::HexArgb),
                 border.isValid() ? border.name(QColor::HexArgb) : QString())
            .arg(scale);
    const auto found = cache.constFind(key);
    if (found != cache.constEnd())
        return *found;
    QImage image(radius * scale, radius * scale,
                 QImage::Format_ARGB32_Premultiplied);
    image.fill(Qt::transparent);
    QPainter painter(&image);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.scale(scale, scale);
    const qreal dx = (corner & 1) ? -radius : 0;
    const qreal dy = (corner & 2) ? -radius : 0;
    painter.setBrush(fill);
    if (border.isValid()) {
        painter.setPen(QPen(border, 1));
        painter.drawRoundedRect(QRectF(dx + 0.5, dy + 0.5, 2 * radius - 1,
                                       2 * radius - 1),
                                radius - 0.5, radius - 0.5);
    } else {
        painter.setPen(Qt::NoPen);
        painter.drawRoundedRect(QRectF(dx, dy, 2 * radius, 2 * radius), radius,
                                radius);
    }
    painter.end();
    const QString markup =
        inlinePixmapMarkup(QPixmap::fromImage(image), radius, radius);
    cache.insert(key, markup);
    return markup;
}

QString roundedPanelHtml(const QString &inner, const QString &width,
                         const QColor &fill, const QColor &border, int radius,
                         int padding, const QString &innerStyle)
{
    const QString fillHex = fill.name();
    const auto side = [&border](const char *edge) {
        return border.isValid() ? QStringLiteral("border-%1:1px solid %2;")
                                      .arg(QLatin1String(edge), border.name())
                                : QString();
    };
    const auto edgeRow = [&](int left, const char *edge) {
        return QStringLiteral("<tr><td width='%1' style='font-size:1px;'>%2</td>"
                              "<td style='font-size:1px;background:%3;%4'></td>"
                              "<td width='%1' style='font-size:1px;'>%5</td></tr>")
            .arg(radius)
            .arg(roundedCornerMarkup(radius, left, fill, border), fillHex,
                 side(edge), roundedCornerMarkup(radius, left + 1, fill, border));
    };
    const int inset = qMax(0, padding - radius);
    return QStringLiteral("<table%1 cellspacing='0' cellpadding='0'>")
               .arg(width.isEmpty() ? QString()
                                    : QStringLiteral(" width='%1'").arg(width)) +
           edgeRow(0, "top") +
           QStringLiteral("<tr><td style='background:%1;%2'></td>"
                          "<td style='background:%1;padding:%3px;%4'>%5</td>"
                          "<td style='background:%1;%6'></td></tr>")
               .arg(fillHex, side("left"))
               .arg(inset)
               .arg(innerStyle, inner, side("right")) +
           edgeRow(2, "bottom") + QStringLiteral("</table>");
}

