QString mergedBranchFromMergeSubject(const QString &subject)
{
    const QString s = subject.trimmed();
    if (!s.startsWith(QLatin1String("Merge ")))
        return QString();
    if (s.startsWith(QLatin1String("Merge pull request #"))) {
        const int from = s.indexOf(QLatin1String(" from "));
        if (from < 0)
            return QString();
        const QString head = s.mid(from + 6).trimmed().section(QLatin1Char(' '), 0, 0);
        const int slash = head.indexOf(QLatin1Char('/'));
        return slash < 0 ? head : head.mid(slash + 1);
    }
    if (s.startsWith(QLatin1String("Merge branch '"))) {
        const int end = s.indexOf(QLatin1Char('\''), 14);
        return end < 0 ? QString() : s.mid(14, end - 14);
    }
    const int into = s.lastIndexOf(QLatin1String(" into "));
    if (into <= 6)
        return QString();
    return s.mid(6, into - 6).trimmed();
}

void mergeVelocityPeriodStats(QList<qint64> timestamps, qint64 nowSecs,
                                     MergeVelocity *velocity)
{
    constexpr qint64 kHour = 60 * 60;
    constexpr qint64 kDay = 24 * kHour;
    const qint64 lengths[] = {kHour, kDay, 7 * kDay, 30 * kDay, 52 * 7 * kDay};
    const int totals[] = {velocity->lastHour, velocity->last24Hours,
                          velocity->last7Days, velocity->last30Days,
                          velocity->last52Weeks};
    // Same skew rule as the buckets: a few minutes ahead counts as now.
    timestamps.erase(std::remove_if(timestamps.begin(), timestamps.end(),
                                    [nowSecs](qint64 timestamp) {
                                        return timestamp > nowSecs + 5 * 60;
                                    }),
                     timestamps.end());
    for (qint64 &timestamp : timestamps)
        timestamp = qMin(timestamp, nowSecs);
    std::sort(timestamps.begin(), timestamps.end());
    velocity->periodTop = QVector<int>(5, 0);
    velocity->periodAvg = QVector<double>(5, 0.0);
    for (int k = 0; k < 5; ++k) {
        const qint64 length = lengths[k];
        // Windows end on a merge and reach back `length` seconds exclusive,
        // the same (now - length, now] rule the card's own total uses.
        int top = totals[k];
        int first = 0;
        for (int last = 0; last < timestamps.size(); ++last) {
            while (timestamps.at(first) <= timestamps.at(last) - length)
                ++first;
            top = qMax(top, last - first + 1);
        }
        velocity->periodTop[k] = top;
        if (!timestamps.isEmpty()) {
            // Every window of this length that the history touches, so the
            // mean can never exceed the busiest one.
            const qint64 periods =
                (nowSecs - timestamps.first()) / length + 1;
            velocity->periodAvg[k] = double(timestamps.size()) / periods;
        }
    }
}

MergeVelocity mergeVelocityForTimestamps(const QList<qint64> &timestamps,
                                                 qint64 nowSecs)
{
    MergeVelocity velocity;
    constexpr qint64 kMinute = 60;
    constexpr qint64 kHour = 60 * kMinute;
    constexpr qint64 kDay = 24 * kHour;
    for (qint64 timestamp : timestamps) {
        // A commit timestamp a few seconds ahead because of clock skew still
        // belongs to the newest bucket; older/far-future records do not.
        const qint64 age = qMax<qint64>(0, nowSecs - timestamp);
        if (timestamp > nowSecs + 5 * 60 || age >= 52 * 7 * kDay)
            continue;
        ++velocity.weekly[51 - int(age / (7 * kDay))];
        ++velocity.last52Weeks;
        if (age >= 30 * kDay)
            continue;
        ++velocity.monthly[29 - int(age / kDay)];
        ++velocity.last30Days;
        if (age >= 7 * kDay)
            continue;
        const int day = 6 - int(age / kDay);
        ++velocity.daily[day];
        ++velocity.last7Days;
        if (age >= kDay)
            continue;
        const int hour = 23 - int(age / kHour);
        ++velocity.hourly[hour];
        ++velocity.last24Hours;
        if (age >= kHour)
            continue;
        const int minute = 59 - int(age / kMinute);
        ++velocity.minutely[minute];
        ++velocity.lastHour;
    }
    mergeVelocityPeriodStats(timestamps, nowSecs, &velocity);
    return velocity;
}

MergeCertificateData mergeCertificateData(
    const MergeCelebrationRow &landed, const QString &base, int commits,
    const MergeVelocity &velocity)
{
    MergeCertificateData data;
    data.branch = landed.branch;
    data.base = base;
    data.actor = landed.actor;
    data.detail = landed.detail;
    data.mergeCommit = landed.mergeCommit;
    data.whenSecs = landed.whenSecs;
    data.commits = commits;
    data.files = landed.files;
    data.insertions = landed.insertions;
    data.deletions = landed.deletions;
    data.velocity = velocity;
    return data;
}

QString mergeCelebrationRowHref(const MergeCelebrationRow &row)
{
    if (row.branchStillExists && !row.branch.isEmpty())
        return QLatin1String("fmbranch:") +
               QString::fromLatin1(QUrl::toPercentEncoding(row.branch));
    return row.mergeCommit.isEmpty() ? QString()
                                     : QLatin1String("fmcommit:") + row.mergeCommit;
}

QList<MergeActorTally> mergeCelebrationTallies(
    const QList<MergeCelebrationRow> &today, int minMerges)
{
    QList<MergeActorTally> tallies;
    for (const MergeCelebrationRow &row : today) {
        if (row.actor.isEmpty())
            continue; // an unattributed landing belongs to nobody's tally
        int at = -1;
        for (int i = 0; i < tallies.size(); ++i) {
            if (tallies.at(i).actor == row.actor) {
                at = i;
                break;
            }
        }
        if (at < 0) {
            MergeActorTally fresh;
            fresh.actor = row.actor;
            tallies.append(fresh);
            at = tallies.size() - 1;
        }
        MergeActorTally &tally = tallies[at];
        ++tally.merges;
        tally.files += qMax(0, row.files);
        tally.insertions += qMax(0, row.insertions);
        tally.deletions += qMax(0, row.deletions);
        if (tally.avatar.isNull())
            tally.avatar = row.avatar;
    }
    tallies.erase(std::remove_if(tallies.begin(), tallies.end(),
                                 [minMerges](const MergeActorTally &tally) {
                                     return tally.merges < minMerges;
                                 }),
                  tallies.end());
    std::sort(tallies.begin(), tallies.end(),
              [](const MergeActorTally &a, const MergeActorTally &b) {
                  if (a.merges != b.merges)
                      return a.merges > b.merges;
                  return a.actor.localeAwareCompare(b.actor) < 0;
              });
    return tallies;
}

QString mergeChurnHtml(int files, int insertions, int deletions)
{
    QStringList parts;
    if (files > 0)
        parts << (files == 1 ? QStringLiteral("1 file")
                             : QStringLiteral("%1 files").arg(files));
    if (insertions > 0)
        parts << QStringLiteral("<span style='color:#3fb950'>+%1</span>")
                     .arg(insertions);
    if (deletions > 0)
        parts << QString::fromUtf8("<span style='color:#f85149'>\xE2\x88\x92%1"
                                   "</span>")
                     .arg(deletions);
    return parts.join(QStringLiteral(" "));
}

QString mergeRowChurnHtml(const MergeCelebrationRow &row)
{
    return mergeChurnHtml(row.files, row.insertions, row.deletions);
}

QPixmap mergeVelocityChartPixmap(const QVector<int> &source,
                                        const QString &oldestLabel,
                                        int width, int height)
{
    const QVector<int> buckets = source.isEmpty() ? QVector<int>(1, 0) : source;
    const bool dark = Theme::activeDark();
    const QColor text = Theme::color(Theme::Role::FgMuted);
    const QColor grid = Theme::color(Theme::Role::BorderStrong);
    const QColor bar(dark ? QStringLiteral("#56d364")
                          : QStringLiteral("#2da44e"));
    QPixmap chart(width, height);
    chart.fill(Qt::transparent);
    QPainter painter(&chart);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setPen(grid);
    constexpr int kTop = 5;
    constexpr int kBottom = 19;
    const QRect bars(4, kTop, width - 8, height - kTop - kBottom);
    painter.drawLine(bars.bottomLeft(), bars.bottomRight());

    const int peak = qMax(1, *std::max_element(buckets.cbegin(), buckets.cend()));
    const qreal slot = qreal(bars.width()) / buckets.size();
    // A 60- or 52-bar series in a narrow card has under 3px per slot; a 2px
    // gap there would leave the bars overlapping their neighbours.
    const qreal gap = slot < 3.0 ? 0.6 : buckets.size() > 12 ? 2.0 : 5.0;
    const qreal minBar = slot < 3.0 ? 1.0 : 2.0;
    for (int i = 0; i < buckets.size(); ++i) {
        const qreal barHeight = buckets.at(i) <= 0
                                    ? 2.0
                                    : qMax(4.0, qreal(buckets.at(i)) /
                                                        peak * (bars.height() - 5));
        const QRectF rect(bars.left() + i * slot + gap / 2,
                          bars.bottom() - barHeight,
                          qMax(minBar, slot - gap), barHeight);
        painter.setBrush(buckets.at(i) > 0 ? bar : grid);
        painter.setPen(Qt::NoPen);
        painter.drawRoundedRect(rect, 2, 2);
    }

    QFont label = painter.font();
    label.setPointSizeF(qMax(7.0, label.pointSizeF() - 2.0));
    painter.setFont(label);
    painter.setPen(text);
    painter.drawText(QRect(2, height - 16, width / 2, 14),
                     Qt::AlignLeft | Qt::AlignVCenter, oldestLabel);
    painter.drawText(QRect(width / 2, height - 16, width / 2 - 2, 14),
                     Qt::AlignRight | Qt::AlignVCenter, QStringLiteral("now"));
    return chart;
}

QString mergeVelocityHtml(const MergeVelocity &velocity, const QString &heading,
                          bool compact)
{
    const QString fg = Theme::hex(Theme::Role::Fg);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QString green = Theme::hex(Theme::Role::Success);
    const QColor card = Theme::color(Theme::Role::SurfaceRaised);
    const auto velocityCard = [&](const QString &label, const QString &cadence,
                                  int period, int total,
                                  const QVector<int> &buckets,
                                  const QString &oldestLabel) {
        const QString chart = inlinePixmapMarkup(
            mergeVelocityChartPixmap(buckets, oldestLabel, 120, 78), 120, 78);
        const bool known = period < velocity.periodTop.size() &&
                           period < velocity.periodAvg.size();
        const int top =
            known ? qMax(total, velocity.periodTop.at(period)) : total;
        const double avg = known ? velocity.periodAvg.at(period) : double(total);
        const QString avgText =
            avg >= 10.0 || avg == 0.0 ? QString::number(qRound(avg))
                                      : QString::number(avg, 'f', 1);
        const QString stats =
            QString::fromUtf8("top %1 \xC2\xB7 avg %2").arg(top).arg(avgText);
        const QString inner =
            QStringLiteral(
                "<table width='100%' cellspacing='0' cellpadding='0'><tr>"
                "<td style='color:%1;font-size:11px;font-weight:600;"
                "letter-spacing:1px;white-space:nowrap;'>%2"
                "<div style='color:%3;font-size:10px;font-weight:400;"
                "letter-spacing:0px;'>%4</div>"
                "</td><td align='right' valign='top' style='color:%5;"
                "font-size:20px;font-weight:600;'>%6</td></tr></table>"
                "<div style='color:%3;font-size:10px;margin-top:2px;'>%7</div>"
                "<div style='margin-top:4px;'>%8</div>")
                .arg(fg, label, muted, cadence, green)
                .arg(total)
                .arg(stats, chart);
        return QStringLiteral("<td width='%1%' valign='top'>%2</td>")
            .arg(compact ? 33 : 20)
            .arg(roundedPanelHtml(inner, QStringLiteral("100%"), card, QColor(),
                                  8, 9));
    };
    QString html = QStringLiteral(
        "<p style='color:%1;font-size:11px;font-weight:600;letter-spacing:1px;"
        "margin-top:20px;margin-bottom:8px;'>%2</p>"
        "<table width='100%' cellspacing='0' cellpadding='0'><tr>")
                       .arg(muted, heading);
    QStringList cells;
    if (!compact)
        cells << velocityCard(QStringLiteral("1 HOUR"), QStringLiteral("minutely"),
                              0, velocity.lastHour, velocity.minutely,
                              QStringLiteral("60m ago"));
    cells << velocityCard(QStringLiteral("24 HOURS"), QStringLiteral("hourly"),
                          1, velocity.last24Hours, velocity.hourly,
                          QStringLiteral("24h ago"));
    cells << velocityCard(QStringLiteral("7 DAYS"), QStringLiteral("daily"),
                          2, velocity.last7Days, velocity.daily,
                          QStringLiteral("7d ago"));
    cells << velocityCard(QStringLiteral("30 DAYS"), QStringLiteral("daily"),
                          3, velocity.last30Days, velocity.monthly,
                          QStringLiteral("30d ago"));
    if (!compact)
        cells << velocityCard(QStringLiteral("52 WEEKS"), QStringLiteral("weekly"),
                              4, velocity.last52Weeks, velocity.weekly,
                              QStringLiteral("52w ago"));
    html += cells.join(QStringLiteral("<td width='6'></td>"));
    html += QStringLiteral("</tr></table>");
    return html;
}

QString userActivityHeatHtml(const QVector<int> &counts, int nowSlot)
{
    using namespace forkmesh::activity;
    const bool dark = qApp->palette().color(QPalette::Base).lightness() < 128;
    const QString fg = Theme::hex(Theme::Role::Fg);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QString green = Theme::hex(Theme::Role::Success);
    const ActivitySummary summary = summarizeActivity(counts);
    const QSize size = activityHeatSize();
    const QString chart = inlinePixmapMarkup(
        QPixmap::fromImage(activityHeatImage(counts, nowSlot, dark)), size.width(),
        size.height());
    const QLocale locale;
    const auto slotTime = [](int slot) {
        return QTime(slot / kActivitySlotsPerHour,
                     (slot % kActivitySlotsPerHour) * kActivitySlotMinutes)
            .toString(QStringLiteral("HH:mm"));
    };
    const auto stat = [&](const QString &label, const QString &value) {
        return QStringLiteral("<div style='color:%1;font-size:10px;"
                              "letter-spacing:1px;margin-top:10px;'>%2</div>"
                              "<div style='color:%3;font-size:15px;"
                              "font-weight:600;'>%4</div>")
            .arg(muted, label, fg, value);
    };
    QString stats = QStringLiteral("<div style='color:%1;font-size:24px;"
                                   "font-weight:600;'>%2</div>"
                                   "<div style='color:%3;font-size:11px;'>%4"
                                   "</div>")
                        .arg(green, locale.toString(summary.total), muted,
                             summary.total == 1
                                 ? QStringLiteral("interaction today")
                                 : QStringLiteral("interactions today"));
    if (const auto *log = UserActivityLog::instance()) {
        const QStringList others = log->otherKindsFor(QDate::currentDate());
        if (!others.isEmpty())
            stats += QStringLiteral("<div style='color:%1;font-size:11px;'>"
                                    "on %2</div>")
                         .arg(muted, activitySourcesText(QStringLiteral("desktop"),
                                                         others)
                                         .toHtmlEscaped());
    }
    if (summary.total > 0) {
        const int activeMinutes = summary.activeSlots * kActivitySlotMinutes;
        stats += stat(QStringLiteral("ACTIVE"),
                      activeMinutes >= 60
                          ? QStringLiteral("%1h %2m")
                                .arg(activeMinutes / 60)
                                .arg(activeMinutes % 60)
                          : QStringLiteral("%1m").arg(activeMinutes));
        stats += stat(QStringLiteral("BUSIEST HOUR"),
                      QString::fromUtf8("%1 \xC2\xB7 %2")
                          .arg(QTime(summary.peakHour, 0)
                                   .toString(QStringLiteral("HH:mm")),
                               locale.toString(summary.peakHourTotal)));
        stats += stat(QStringLiteral("BUSIEST 5 MIN"),
                      QString::fromUtf8("%1 \xC2\xB7 %2")
                          .arg(slotTime(summary.peakSlot),
                               locale.toString(summary.peak)));
    } else {
        stats += QStringLiteral("<div style='color:%1;font-size:11px;"
                                "margin-top:10px;'>Clicks, keys, scrolls and "
                                "taps show up here as you work.</div>")
                     .arg(muted);
    }
    const QString body =
        QStringLiteral("<table width='100%' cellspacing='0' cellpadding='0'><tr>"
                       "<td valign='top'>%1</td>"
                       "<td valign='top' style='padding:0 4px 0 12px;'>%2</td>"
                       "</tr></table>")
            .arg(chart, stats);
    return certificateColumnHtml(
        certificateHeadingHtml(QStringLiteral(
            "TODAY&#8217;S ACTIVITY &#183; EVERY CLICK, KEY, SCROLL AND TAP")) +
        roundedPanelHtml(body, QStringLiteral("100%"),
                         Theme::color(Theme::Role::Surface),
                         Theme::color(Theme::Role::Border), 12, 16));
}

QJsonArray mergeVelocityJson(const QVector<int> &values)
{
    QJsonArray array;
    for (int value : values)
        array.append(value);
    return array;
}

QVector<int> mergeVelocityFromJson(const QJsonValue &value, int size)
{
    QVector<int> result(size, 0);
    const QJsonArray array = value.toArray();
    for (int i = 0; i < qMin(size, int(array.size())); ++i)
        result[i] = qBound(0, array.at(i).toInt(), 1000000);
    return result;
}

QUrl mergeCertificateShareUrl(const QString &platform,
                                     const MergeCertificateData &data)
{
    const QJsonObject object{
        {QStringLiteral("branch"), data.branch.left(512)},
        {QStringLiteral("base"), data.base.left(512)},
        {QStringLiteral("actor"), data.actor.left(256)},
        {QStringLiteral("detail"), data.detail.left(512)},
        {QStringLiteral("commit"), data.mergeCommit.left(80)},
        {QStringLiteral("when"), double(data.whenSecs)},
        {QStringLiteral("commits"), data.commits},
        {QStringLiteral("files"), data.files},
        {QStringLiteral("insertions"), data.insertions},
        {QStringLiteral("deletions"), data.deletions},
        {QStringLiteral("minutely"), mergeVelocityJson(data.velocity.minutely)},
        {QStringLiteral("hourly"), mergeVelocityJson(data.velocity.hourly)},
        {QStringLiteral("daily"), mergeVelocityJson(data.velocity.daily)},
        {QStringLiteral("monthly"), mergeVelocityJson(data.velocity.monthly)},
    };
    // Three self-contained links sit in the certificate HTML. Compress the
    // minute/hour/day/month series once per link so a portrait-heavy merge day still
    // fits the rich-text safety budget. The leading marker distinguishes this
    // representation from links created before compression was introduced.
    const QByteArray payload =
        qCompress(QJsonDocument(object).toJson(QJsonDocument::Compact), 9)
            .toBase64(QByteArray::Base64UrlEncoding |
                      QByteArray::OmitTrailingEquals);
    QUrl url(QStringLiteral("fmmergeshare:%1").arg(platform));
    QUrlQuery query;
    query.addQueryItem(QStringLiteral("certificate"),
                       QLatin1Char('z') + QString::fromLatin1(payload));
    url.setQuery(query);
    return url;
}

bool mergeCertificateDataFromUrl(const QUrl &url,
                                        MergeCertificateData *data)
{
    if (!data || url.scheme() != QLatin1String("fmmergeshare"))
        return false;
    const QString encoded = QUrlQuery(url).queryItemValue(
        QStringLiteral("certificate"), QUrl::FullyDecoded);
    const bool compressed = encoded.startsWith(QLatin1Char('z'));
    QByteArray payload = QByteArray::fromBase64(
        (compressed ? encoded.mid(1) : encoded).toLatin1(),
        QByteArray::Base64UrlEncoding);
    if (compressed) {
        // qCompress prefixes a big-endian uncompressed length. Bound it before
        // qUncompress allocates so a crafted share URL cannot request a large
        // buffer from the UI process.
        if (payload.size() < 4)
            return false;
        const quint32 expandedSize =
            (quint32(quint8(payload.at(0))) << 24) |
            (quint32(quint8(payload.at(1))) << 16) |
            (quint32(quint8(payload.at(2))) << 8) |
            quint32(quint8(payload.at(3)));
        constexpr quint32 kMaxCertificatePayload = 64 * 1024;
        if (expandedSize == 0 || expandedSize > kMaxCertificatePayload)
            return false;
        payload = qUncompress(payload);
        if (payload.size() != qsizetype(expandedSize))
            return false;
    }
    QJsonParseError error;
    const QJsonDocument document = QJsonDocument::fromJson(payload, &error);
    if (error.error != QJsonParseError::NoError || !document.isObject())
        return false;
    const QJsonObject object = document.object();
    MergeCertificateData decoded;
    decoded.branch = object.value(QStringLiteral("branch")).toString().left(512);
    decoded.base = object.value(QStringLiteral("base")).toString().left(512);
    if (decoded.branch.isEmpty() || decoded.base.isEmpty())
        return false;
    decoded.actor = object.value(QStringLiteral("actor")).toString().left(256);
    decoded.detail = object.value(QStringLiteral("detail")).toString().left(512);
    decoded.mergeCommit =
        object.value(QStringLiteral("commit")).toString().left(80);
    decoded.whenSecs =
        qMax<qint64>(0, qint64(object.value(QStringLiteral("when")).toDouble()));
    decoded.commits = qBound(-1, object.value(QStringLiteral("commits")).toInt(),
                             1000000);
    decoded.files = qBound(0, object.value(QStringLiteral("files")).toInt(),
                           1000000);
    decoded.insertions =
        qBound(0, object.value(QStringLiteral("insertions")).toInt(), 100000000);
    decoded.deletions =
        qBound(0, object.value(QStringLiteral("deletions")).toInt(), 100000000);
    decoded.velocity.minutely =
        mergeVelocityFromJson(object.value(QStringLiteral("minutely")), 60);
    decoded.velocity.hourly =
        mergeVelocityFromJson(object.value(QStringLiteral("hourly")), 24);
    decoded.velocity.daily =
        mergeVelocityFromJson(object.value(QStringLiteral("daily")), 7);
    // Share links made before the one-hour chart existed have only hourly
    // buckets. Preserve their newest-hour total in the new chart.
    if (!object.contains(QStringLiteral("minutely")) &&
        !decoded.velocity.hourly.isEmpty())
        decoded.velocity.minutely.last() = decoded.velocity.hourly.last();
    decoded.velocity.monthly =
        mergeVelocityFromJson(object.value(QStringLiteral("monthly")), 30);
    // Links from before the 30-day chart carry its newest seven slices as the
    // daily series; both use the same rolling 24-hour boundaries.
    if (!object.contains(QStringLiteral("monthly")))
        std::copy(decoded.velocity.daily.cbegin(), decoded.velocity.daily.cend(),
                  decoded.velocity.monthly.end() - decoded.velocity.daily.size());
    decoded.velocity.last30Days =
        std::accumulate(decoded.velocity.monthly.cbegin(),
                        decoded.velocity.monthly.cend(), 0);
    decoded.velocity.lastHour =
        std::accumulate(decoded.velocity.minutely.cbegin(),
                        decoded.velocity.minutely.cend(), 0);
    decoded.velocity.last24Hours =
        std::accumulate(decoded.velocity.hourly.cbegin(),
                        decoded.velocity.hourly.cend(), 0);
    decoded.velocity.last7Days =
        std::accumulate(decoded.velocity.daily.cbegin(),
                        decoded.velocity.daily.cend(), 0);
    *data = decoded;
    return true;
}

QString mergeCertificateShortName(const QString &value, int limit)
{
    if (value.size() <= limit)
        return value;
    return value.left(qMax(1, limit - 1)) + QChar(0x2026);
}

QString mergeCertificateShareTitle(const MergeCertificateData &data)
{
    return QStringLiteral("Merged %1 into %2 with ForkMesh")
        .arg(mergeCertificateShortName(data.branch, 70),
             mergeCertificateShortName(data.base, 40));
}

QString mergeCertificateShareText(const MergeCertificateData &data)
{
    return QStringLiteral("%1.\n\nMerge velocity: %2 / 1h %3 %4 / 24h %3 "
                          "%5 / 7d %3 %6 / 30d\n"
                          "https://forkmesh.com")
        .arg(mergeCertificateShareTitle(data))
        .arg(data.velocity.lastHour)
        .arg(QChar(0x00b7))
        .arg(data.velocity.last24Hours)
        .arg(data.velocity.last7Days)
        .arg(data.velocity.last30Days);
}

QUrl mergeCertificateComposerUrl(const QString &platform,
                                        const MergeCertificateData &data)
{
    QUrl target;
    QUrlQuery query;
    if (platform == QLatin1String("reddit")) {
        target = QUrl(QStringLiteral("https://www.reddit.com/submit"));
        query.addQueryItem(QStringLiteral("title"),
                           mergeCertificateShareTitle(data));
    } else if (platform == QLatin1String("twitter")) {
        target = QUrl(QStringLiteral("https://x.com/intent/tweet"));
        query.addQueryItem(QStringLiteral("text"),
                           mergeCertificateShareText(data));
    } else if (platform == QLatin1String("mastodon")) {
        target = QUrl(QStringLiteral("https://share.joinmastodon.org/"));
        query.addQueryItem(QStringLiteral("text"),
                           mergeCertificateShareText(data));
    } else {
        return QUrl();
    }
    target.setQuery(query);
    return target;
}

QImage mergeCertificateImage(const MergeCertificateData &data)
{
    constexpr int kWidth = 1200;
    constexpr int kHeight = 675;
    QImage image(kWidth, kHeight, QImage::Format_ARGB32_Premultiplied);
    QLinearGradient paper(0, 0, kWidth, kHeight);
    paper.setColorAt(0, QColor(QStringLiteral("#fffdf7")));
    paper.setColorAt(1, QColor(QStringLiteral("#f4efe1")));
    image.fill(Qt::transparent);
    QPainter painter(&image);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.fillRect(image.rect(), paper);

    painter.setBrush(Qt::NoBrush);
    painter.setPen(QPen(QColor(QStringLiteral("#1f7a42")), 5));
    painter.drawRect(QRect(24, 24, kWidth - 49, kHeight - 49));
    painter.setPen(QPen(QColor(QStringLiteral("#c9a227")), 2));
    painter.drawRect(QRect(36, 36, kWidth - 73, kHeight - 73));

    const QImage logo(QStringLiteral(":/app/forkmesh.png"));
    if (!logo.isNull())
        painter.drawImage(QRect(68, 55, 76, 76), logo);

    QFont font = painter.font();
    font.setBold(true);
    font.setPointSize(18);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#193c2a")));
    painter.drawText(QRect(164, 58, 360, 34), Qt::AlignLeft | Qt::AlignVCenter,
                     QStringLiteral("FORKMESH"));
    font.setBold(false);
    font.setPointSize(10);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#66756b")));
    painter.drawText(QRect(164, 92, 420, 25), Qt::AlignLeft | Qt::AlignVCenter,
                     QStringLiteral("INDEPENDENT SOURCE-CODE HOSTING"));
    painter.drawText(QRect(820, 60, 300, 30), Qt::AlignRight | Qt::AlignVCenter,
                     QStringLiteral("forkmesh.com"));
    painter.setPen(QColor(QStringLiteral("#d7cda9")));
    painter.drawLine(68, 140, 1132, 140);

    font.setBold(true);
    font.setLetterSpacing(QFont::AbsoluteSpacing, 3.0);
    font.setPointSize(12);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#9a7620")));
    painter.drawText(QRect(80, 158, 1040, 28), Qt::AlignCenter,
                     QStringLiteral("CERTIFICATE OF MERGE"));
    font.setLetterSpacing(QFont::PercentageSpacing, 100);
    font.setPointSize(27);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#18251d")));
    const QString branch = QFontMetrics(font).elidedText(
        data.branch, Qt::ElideMiddle, 930);
    painter.drawText(QRect(110, 195, 980, 46), Qt::AlignCenter, branch);

    font.setBold(false);
    font.setPointSize(13);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#66756b")));
    painter.drawText(QRect(100, 243, 1000, 30), Qt::AlignCenter,
                     QStringLiteral("has been successfully merged into"));
    font.setBold(true);
    font.setPointSize(18);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#1f7a42")));
    painter.drawText(QRect(100, 274, 1000, 34), Qt::AlignCenter,
                     QFontMetrics(font).elidedText(data.base, Qt::ElideMiddle, 700));

    font.setBold(false);
    font.setPointSize(11);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#66756b")));
    QString credit = data.actor.isEmpty()
                         ? QStringLiteral("Merged successfully")
                         : QStringLiteral("Merged by %1").arg(data.actor);
    if (data.whenSecs > 0)
        credit += QStringLiteral("  %1  %2")
                      .arg(QChar(0x00b7),
                           QLocale().toString(
                               QDateTime::fromSecsSinceEpoch(data.whenSecs),
                               QLocale::ShortFormat));
    painter.drawText(QRect(100, 313, 1000, 28), Qt::AlignCenter, credit);

    struct Stat {
        QString label;
        QString value;
        QColor color;
    };
    const QList<Stat> stats{
        {QStringLiteral("COMMITS"), data.commits >= 0 ? QString::number(data.commits)
                                                      : QStringLiteral("\u2014"),
         QColor(QStringLiteral("#18251d"))},
        {QStringLiteral("FILES"), QString::number(data.files),
         QColor(QStringLiteral("#18251d"))},
        {QStringLiteral("INSERTIONS"), QStringLiteral("+%1").arg(data.insertions),
         QColor(QStringLiteral("#1f883d"))},
        {QStringLiteral("DELETIONS"), QString(QChar(0x2212)) +
                                         QString::number(data.deletions),
         QColor(QStringLiteral("#cf4c44"))},
    };
    constexpr int kStatWidth = 230;
    constexpr int kStatGap = 20;
    constexpr int kStatsLeft =
        (kWidth - (4 * kStatWidth + 3 * kStatGap)) / 2;
    for (int i = 0; i < stats.size(); ++i) {
        const QRect box(kStatsLeft + i * (kStatWidth + kStatGap), 359,
                        kStatWidth, 84);
        painter.setBrush(QColor(QStringLiteral("#fffefa")));
        painter.setPen(QPen(QColor(QStringLiteral("#ddd3b7")), 1));
        painter.drawRoundedRect(box, 5, 5);
        font.setBold(true);
        font.setPointSize(20);
        painter.setFont(font);
        painter.setPen(stats.at(i).color);
        painter.drawText(QRect(box.left(), box.top() + 10, box.width(), 34),
                         Qt::AlignCenter, stats.at(i).value);
        font.setBold(true);
        font.setPointSize(9);
        painter.setFont(font);
        painter.setPen(QColor(QStringLiteral("#7a817c")));
        painter.drawText(QRect(box.left(), box.top() + 48, box.width(), 22),
                         Qt::AlignCenter, stats.at(i).label);
    }

    const auto drawVelocity = [&](const QRect &box, const QVector<int> &buckets,
                                  int total, const QString &label,
                                  const QString &oldest) {
        painter.setBrush(QColor(QStringLiteral("#edf5ee")));
        painter.setPen(QPen(QColor(QStringLiteral("#c7d8ca")), 1));
        painter.drawRoundedRect(box, 5, 5);
        font.setBold(true);
        font.setPointSize(10);
        painter.setFont(font);
        painter.setPen(QColor(QStringLiteral("#355642")));
        painter.drawText(QRect(box.left() + 14, box.top() + 9, box.width() - 90, 22),
                         Qt::AlignLeft | Qt::AlignVCenter, label);
        font.setPointSize(19);
        painter.setFont(font);
        painter.setPen(QColor(QStringLiteral("#1f883d")));
        painter.drawText(QRect(box.right() - 76, box.top() + 5, 62, 30),
                         Qt::AlignRight | Qt::AlignVCenter, QString::number(total));
        const QRect bars(box.left() + 14, box.top() + 37, box.width() - 28, 46);
        const int peak = qMax(1, buckets.isEmpty()
                                     ? 0
                                     : *std::max_element(buckets.cbegin(),
                                                         buckets.cend()));
        const qreal slot = buckets.isEmpty() ? bars.width()
                                             : qreal(bars.width()) / buckets.size();
        const qreal gap = buckets.size() > 12 ? 2.0 : 5.0;
        painter.setPen(Qt::NoPen);
        for (int i = 0; i < buckets.size(); ++i) {
            const qreal h = buckets.at(i) <= 0
                                ? 2.0
                                : qMax(4.0, qreal(buckets.at(i)) / peak * 38.0);
            painter.setBrush(buckets.at(i) > 0
                                 ? QColor(QStringLiteral("#2da44e"))
                                 : QColor(QStringLiteral("#c7d8ca")));
            painter.drawRoundedRect(
                QRectF(bars.left() + i * slot + gap / 2, bars.bottom() - h,
                       qMax(2.0, slot - gap), h),
                2, 2);
        }
        font.setBold(false);
        font.setPointSize(8);
        painter.setFont(font);
        painter.setPen(QColor(QStringLiteral("#7a817c")));
        painter.drawText(QRect(box.left() + 14, box.bottom() - 18, 100, 14),
                         Qt::AlignLeft, oldest);
        painter.drawText(QRect(box.right() - 114, box.bottom() - 18, 100, 14),
                         Qt::AlignRight, QStringLiteral("now"));
    };
    constexpr int kVelocityWidth = 251;
    constexpr int kVelocityGap = 20;
    const auto velocityBox = [](int index) {
        return QRect(68 + index * (kVelocityWidth + kVelocityGap), 468,
                     kVelocityWidth, 112);
    };
    drawVelocity(velocityBox(0), data.velocity.minutely,
                 data.velocity.lastHour, QStringLiteral("1-HOUR VELOCITY"),
                 QStringLiteral("60m ago"));
    drawVelocity(velocityBox(1), data.velocity.hourly,
                 data.velocity.last24Hours, QStringLiteral("24-HOUR VELOCITY"),
                 QStringLiteral("24h ago"));
    drawVelocity(velocityBox(2), data.velocity.daily,
                 data.velocity.last7Days, QStringLiteral("7-DAY VELOCITY"),
                 QStringLiteral("7d ago"));
    drawVelocity(velocityBox(3), data.velocity.monthly,
                 data.velocity.last30Days, QStringLiteral("30-DAY VELOCITY"),
                 QStringLiteral("30d ago"));

    font.setBold(false);
    font.setPointSize(9);
    painter.setFont(font);
    painter.setPen(QColor(QStringLiteral("#7a817c")));
    const QString certificateId = data.mergeCommit.isEmpty()
                                      ? QStringLiteral("FORKMESH MERGE CERTIFICATE")
                                      : QStringLiteral("CERTIFICATE %1")
                                            .arg(data.mergeCommit.left(12).toUpper());
    painter.drawText(QRect(68, 609, 500, 24), Qt::AlignLeft | Qt::AlignVCenter,
                     certificateId);
    painter.drawText(QRect(632, 609, 500, 24), Qt::AlignRight | Qt::AlignVCenter,
                     QStringLiteral("BUILT AND MERGED WITH FORKMESH"));
    painter.end();
    return image;
}

QString mergeCertificateShareButtonsHtml(
    const MergeCertificateData &data)
{
    const QColor fg = Theme::color(Theme::Role::Fg);
    const QColor button = Theme::color(Theme::Role::SurfaceRaised);
    const QColor border = Theme::color(Theme::Role::BorderStrong);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    struct ShareButton {
        const char *platform;
        const char *label;
        const char *icon;
    };
    static const ShareButton buttons[] = {
        {"reddit", "Reddit", "reddit"},
        {"twitter", "Twitter", "twitter-bird"},
        {"mastodon", "Mastodon", "mastodon"},
    };
    QString html =
        certificateHeadingHtml(QStringLiteral("SHARE THIS CERTIFICATE")) +
        QStringLiteral("<table cellspacing='0' cellpadding='0'><tr>");
    bool first = true;
    for (const ShareButton &entry : buttons) {
        const QString href =
            mergeCertificateShareUrl(QString::fromLatin1(entry.platform), data)
                .toString(QUrl::FullyEncoded)
                .toHtmlEscaped();
        const QString icon = inlinePixmapMarkup(
            tintedOcticonPixmap(QString::fromLatin1(entry.icon), fg, 14), 14);
        const QString label =
            QStringLiteral("<a href='%1' style='color:%2;text-decoration:none;"
                           "font-size:12px;font-weight:600;'>%3&nbsp;&nbsp;%4"
                           "&nbsp;</a>")
                .arg(href, fg.name(), icon, QString::fromLatin1(entry.label));
        if (!first)
            html += QStringLiteral("<td width='8'></td>");
        first = false;
        html += QStringLiteral("<td>%1</td>")
                    .arg(roundedPanelHtml(label, QString(), button, border, 6,
                                          8, QStringLiteral("white-space:nowrap;")));
    }
    html += QStringLiteral(
                "</tr></table><p style='color:%1;font-size:11px;margin-top:8px;"
                "margin-bottom:0px;'>The certificate image is copied for you to "
                "paste into the composer.</p>")
                .arg(muted);
    return html;
}

QString mergeSectionHeadingHtml(const QString &text)
{
    return certificateHeadingHtml(text);
}

const MergeRangeSpec *mergeRangeSpecs()
{
    static const MergeRangeSpec specs[kMergeRangeCount] = {
        {"24h", "24h", "PAST 24 HOURS", "in the past 24 hours", 1},
        {"7d", "7d", "PAST 7 DAYS", "in the past 7 days", 7},
        {"30d", "30d", "PAST 30 DAYS", "in the past 30 days", 30},
        {"6m", "6m", "PAST 6 MONTHS", "in the past 6 months", 183},
    };
    return specs;
}

int clampedMergeRange(int index)
{
    return index < 0 ? 0 : (index >= kMergeRangeCount ? kMergeRangeCount - 1 : index);
}

const MergeRangeSpec &mergeRangeSpec(int index)
{
    return mergeRangeSpecs()[clampedMergeRange(index)];
}

int mergeRangeIndexForKey(const QString &key)
{
    for (int i = 0; i < kMergeRangeCount; ++i)
        if (key == QLatin1String(mergeRangeSpecs()[i].key))
            return i;
    return 0;
}

QString mergeRangeHeading(int index)
{
    return QString::fromLatin1(mergeRangeSpec(index).heading);
}

QString mergeRangePhrase(int index)
{
    return QString::fromLatin1(mergeRangeSpec(index).phrase);
}

QString mergeRangePickerHtml(int selected)
{
    const QColor restBg = Theme::color(Theme::Role::SurfaceRaised);
    const QColor onBg = Theme::color(Theme::Role::AccentSubtle);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QString onFg = Theme::hex(Theme::Role::AccentFg);
    QString html = QStringLiteral("<table cellspacing='0' cellpadding='0'><tr>");
    for (int i = 0; i < kMergeRangeCount; ++i) {
        const bool on = i == clampedMergeRange(selected);
        if (i > 0)
            html += QStringLiteral("<td width='4'></td>");
        const QString link =
            QStringLiteral("<a href='fmmergerange:%1' style='color:%2;"
                           "text-decoration:none;font-size:11px;"
                           "font-weight:600;'>%3</a>")
                .arg(QString::fromLatin1(mergeRangeSpec(i).key), on ? onFg : muted,
                     QString::fromLatin1(mergeRangeSpec(i).button));
        html += QStringLiteral("<td>%1</td>")
                    .arg(roundedPanelHtml(link, QString(), on ? onBg : restBg,
                                          QColor(), 6, 6,
                                          QStringLiteral("padding:0px 4px;")));
    }
    html += QStringLiteral("</tr></table>");
    return html;
}

QString mergeRangeHeaderHtml(const QString &text, int selected)
{
    return QStringLiteral("<table width='100%' cellspacing='0' cellpadding='0'>"
                          "<tr><td valign='middle'>%1</td>"
                          "<td align='right' valign='middle'>%2</td></tr></table>")
        .arg(mergeSectionHeadingHtml(text), mergeRangePickerHtml(selected));
}

QString certificateListHtml(const QStringList &rows, int highlighted)
{
    const QColor surface = Theme::color(Theme::Role::Surface);
    const QColor border = Theme::color(Theme::Role::Border);
    const QColor tint = Theme::color(Theme::Role::SuccessSubtle);
    QString body = QStringLiteral("<table width='100%' cellspacing='0' "
                                  "cellpadding='0'>");
    for (int i = 0; i < rows.size(); ++i) {
        if (i == highlighted) {
            body += QStringLiteral("<tr><td style='padding:2px 0px;'>%1</td></tr>")
                        .arg(roundedPanelHtml(rows.at(i), QStringLiteral("100%"),
                                              tint, QColor(), 8, 8,
                                              QStringLiteral("padding:2px 0px;")));
            continue;
        }
        const bool divider = i > 0 && i - 1 != highlighted;
        body += QStringLiteral("<tr><td style='padding:10px 8px;%1'>%2</td></tr>")
                    .arg(divider ? QStringLiteral("border-top:1px solid %1;")
                                       .arg(border.name())
                                 : QString(),
                         rows.at(i));
    }
    body += QStringLiteral("</table>");
    return roundedPanelHtml(body, QStringLiteral("100%"), surface, border, 12, 12);
}

QString mergeActorTalliesHtml(const QList<MergeActorTally> &allTallies,
                                     const QString &heading)
{
    if (allTallies.isEmpty())
        return QString();
    constexpr int kMergeTallyLimit = 12;
    const int droppedActors = qMax(0, int(allTallies.size()) - kMergeTallyLimit);
    const QList<MergeActorTally> tallies =
        droppedActors > 0 ? allTallies.mid(0, kMergeTallyLimit) : allTallies;
    const QString fg = Theme::hex(Theme::Role::Fg);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QString green = Theme::hex(Theme::Role::Success);
    QStringList rows;
    for (const MergeActorTally &tally : tallies) {
        const QString churn =
            mergeChurnHtml(tally.files, tally.insertions, tally.deletions);
        rows << QStringLiteral(
                    "<table width='100%' cellspacing='0' cellpadding='0'><tr>"
                    "<td width='34' valign='middle'>%1</td>"
                    "<td valign='middle'><b style='color:%2'>%3</b>%4</td>"
                    "<td align='right' valign='middle'>"
                    "<b style='color:%5;font-size:16px;'>%6</b>"
                    "<span style='color:%7;font-size:11px;'>%8</span>"
                    "</td></tr></table>")
                    .arg(tally.avatar.isNull()
                             ? QString()
                             : inlinePixmapMarkup(tally.avatar, 24),
                         fg, tally.actor.toHtmlEscaped(),
                         churn.isEmpty()
                             ? QString()
                             : QStringLiteral("<div style='font-size:11px;"
                                              "color:%1;'>%2</div>")
                                   .arg(muted, churn),
                         green)
                    .arg(tally.merges)
                    .arg(muted,
                         tally.merges == 1 ? QStringLiteral(" merge")
                                           : QStringLiteral(" merges"));
    }
    QString html = mergeSectionHeadingHtml(heading) + certificateListHtml(rows, -1);
    if (droppedActors > 0)
        html += QStringLiteral("<p style='color:%1;font-size:11px;'>"
                               "%2 more %3 not listed.</p>")
                    .arg(muted)
                    .arg(droppedActors)
                    .arg(droppedActors == 1 ? QStringLiteral("merger is")
                                            : QStringLiteral("mergers are"));
    return html;
}

QString mergeDayRowsHtml(const QList<MergeCelebrationRow> &recent,
                                const QString &base, int truncated, int range)
{
    if (recent.isEmpty())
        return QString();
    const QString fg = Theme::hex(Theme::Role::Fg);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QString link = Theme::hex(Theme::Role::AccentFg);
    const QString green = Theme::hex(Theme::Role::Success);

    QString html = mergeRangeHeaderHtml(
        QStringLiteral("MERGED INTO %1 &#183; %2 &#183; %3")
            .arg(base.toHtmlEscaped().toUpper(), mergeRangeHeading(range))
            .arg(recent.size() + truncated),
        range);
    const qint64 nowSecs = QDateTime::currentSecsSinceEpoch();
    QStringList rows;
    int highlighted = -1;
    for (const MergeCelebrationRow &row : recent) {
        if (row.current && highlighted < 0)
            highlighted = rows.size();
        const QString name =
            row.branch.isEmpty() ? row.mergeCommit.left(8) : row.branch;
        const QString href = mergeCelebrationRowHref(row);
        const QString title =
            href.isEmpty()
                ? QStringLiteral("<b style='color:%1'>%2</b>")
                      .arg(fg, name.toHtmlEscaped())
                : QStringLiteral("<a href='%1' style='color:%2;"
                                 "text-decoration:none;font-weight:600;'>%3</a>")
                      .arg(href, link, name.toHtmlEscaped());
        QStringList meta;
        if (!row.actor.isEmpty())
            meta << row.actor.toHtmlEscaped();
        if (!row.detail.isEmpty())
            meta << row.detail.toHtmlEscaped();
        if (row.whenSecs > 0)
            meta << QDateTime::fromSecsSinceEpoch(row.whenSecs)
                        .toString(nowSecs - row.whenSecs > 86400
                                      ? QStringLiteral("MMM d HH:mm")
                                      : QStringLiteral("HH:mm"));
        const QString rowChurn = mergeRowChurnHtml(row);
        if (!rowChurn.isEmpty())
            meta << rowChurn;
        rows << QStringLiteral(
                    "<table width='100%' cellspacing='0' cellpadding='0'><tr>"
                    "<td width='34' valign='middle'>%1</td>"
                    "<td valign='middle'>%2%3<div style='font-size:11px;"
                    "color:%4;'>%5</div></td></tr></table>")
                    .arg(row.avatar.isNull() ? QString()
                                             : inlinePixmapMarkup(row.avatar, 24),
                         title,
                         row.justNow
                             ? QStringLiteral(" <span style='color:%1;"
                                              "font-size:11px;'>just now</span>")
                                   .arg(green)
                             : QString(),
                         muted, meta.join(QString::fromUtf8(" \xC2\xB7 ")));
    }
    html += certificateListHtml(rows, highlighted);
    if (truncated > 0)
        html += QStringLiteral("<p style='color:%1;font-size:11px;'>"
                               "%2 earlier %3 %4 are not listed.</p>")
                    .arg(muted)
                    .arg(truncated)
                    .arg(truncated == 1 ? QStringLiteral("merge")
                                        : QStringLiteral("merges"),
                         mergeRangePhrase(range));
    return html;
}

static QString mergePaneHtml(const QStringList &sections)
{
    QStringList kept;
    for (const QString &section : sections)
        if (!section.isEmpty())
            kept << section;
    QStringList wrapped;
    for (int i = 0; i < kept.size(); ++i)
        wrapped << QStringLiteral("<div style='padding:%1px 10px %2px 10px;'>")
                           .arg(i == 0 ? 6 : 0)
                           .arg(i == kept.size() - 1 ? 10 : 0) +
                       kept.at(i) + QStringLiteral("</div>");
    return wrapped.join(diffSectionBreakHtml());
}

QString certificateCardHtml(const QString &title, const QString &eyebrow,
                            const QPixmap &avatar, const QString &headline,
                            const QString &statement, const QString &credit,
                            const QString &below, const QString &width)
{
    const QString fg = Theme::hex(Theme::Role::Fg);
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QColor success = Theme::color(Theme::Role::Success);
    const QColor heroFill = Theme::color(Theme::Role::SuccessSubtle);
    const QColor heroBorder =
        QColor::fromRgbF(heroFill.redF() * 0.6 + success.redF() * 0.4,
                         heroFill.greenF() * 0.6 + success.greenF() * 0.4,
                         heroFill.blueF() * 0.6 + success.blueF() * 0.4);

    QPixmap logo(QStringLiteral(":/app/forkmesh.png"));
    if (!logo.isNull())
        logo = logo.scaled(36, 36, Qt::KeepAspectRatio, Qt::SmoothTransformation);
    QString html = QStringLiteral(
                       "<table width='100%' cellspacing='0' cellpadding='0'><tr>"
                       "<td width='48' valign='middle'>%1</td>"
                       "<td valign='middle'><div style='color:%2;font-size:14px;"
                       "font-weight:600;'>ForkMesh</div>"
                       "<div style='color:%3;font-size:11px;'>%4</div></td>"
                       "<td align='right' valign='middle'>"
                       "<div style='color:%5;font-size:10px;font-weight:600;"
                       "letter-spacing:2px;'>%6</div>"
                       "<div style='color:%3;font-size:11px;'>forkmesh.com</div>"
                       "</td></tr></table>"
                       "<div style='font-size:1px;margin-top:15px;'>&nbsp;</div>")
                       .arg(inlinePixmapMarkup(logo, 36), fg, muted, title,
                            success.name(), eyebrow);
    QString hero = QStringLiteral("<table width='100%' cellspacing='0' "
                                  "cellpadding='0'><tr>");
    if (!avatar.isNull())
        hero += QStringLiteral("<td width='72' valign='middle'>%1</td>")
                    .arg(inlinePixmapMarkup(avatar, 56));
    hero += QStringLiteral(
                "<td valign='middle'>"
                "<div style='font-size:22px;font-weight:600;color:%1;'>%2</div>"
                "<div style='font-size:15px;color:%3;margin-top:2px;'>%4</div>"
                "<div style='font-size:12px;color:%5;margin-top:4px;'>%6</div>"
                "</td></tr></table>")
                .arg(success.name(), headline, fg, statement, muted, credit);
    html += roundedPanelHtml(hero, QStringLiteral("100%"), heroFill, heroBorder,
                             12, 18);
    html += below;
    return roundedPanelHtml(html, width, Theme::color(Theme::Role::Surface),
                            Theme::color(Theme::Role::Border), 12, 24,
                            certificateFontStyle());
}

QStringList mergeCertificateHtml(
    const MergeCelebrationRow &landed, const QString &base, int commits,
    const MergeVelocity &velocity, const QList<MergeActorTally> &tallies,
    const QString &talliesHeading, bool alreadyLanded)
{
    const QString fg = Theme::hex(Theme::Role::Fg);

    QStringList credit;
    if (!landed.actor.isEmpty())
        credit << QStringLiteral("by <b style='color:%1'>%2</b>")
                      .arg(fg, landed.actor.toHtmlEscaped());
    if (!landed.detail.isEmpty())
        credit << landed.detail.toHtmlEscaped();
    if (landed.whenSecs > 0)
        credit << formatIssueRelativeTime(landed.whenSecs * 1000);
    if (commits > 0)
        credit << (commits == 1 ? QStringLiteral("1 commit")
                                : QStringLiteral("%1 commits").arg(commits));
    const QString landedChurn = mergeRowChurnHtml(landed);
    if (!landedChurn.isEmpty())
        credit << landedChurn;

    const MergeCertificateData certificate =
        mergeCertificateData(landed, base, commits, velocity);
    const QString relationship =
        alreadyLanded
            ? QStringLiteral("<b style='font-family:monospace;'>%1</b> already "
                             "landed in <b style='font-family:monospace;'>%2</b>.")
                  .arg(landed.branch.toHtmlEscaped(), base.toHtmlEscaped())
            : QStringLiteral("<b style='font-family:monospace;'>%1</b> is part "
                             "of <b style='font-family:monospace;'>%2</b> now.")
                  .arg(landed.branch.toHtmlEscaped(), base.toHtmlEscaped());
    const QString html = QStringLiteral("<table width='760' align='center' "
                                        "cellspacing='0' cellpadding='0'><tr><td>") +
                         certificateCardHtml(
                             QStringLiteral("Merge certificate"),
                             QStringLiteral("CERTIFICATE OF MERGE"), landed.avatar,
                             alreadyLanded ? QStringLiteral("&#10003; Merged")
                                           : QStringLiteral("&#10003; Merged!"),
                             relationship,
                             credit.join(QString::fromUtf8(" \xC2\xB7 ")),
                             mergeVelocityHtml(velocity) +
                                 mergeCertificateShareButtonsHtml(certificate),
                             QStringLiteral("100%")) +
                         QStringLiteral("</td></tr></table>");
    const QString leaderboard = mergeActorTalliesHtml(tallies, talliesHeading);
    if (leaderboard.isEmpty())
        return {html};
    return {html, certificateColumnHtml(leaderboard)};
}

QString pullCertificateHtml(const PullCertificateData &data)
{
    const QString fg = Theme::hex(Theme::Role::Fg);
    QStringList credit;
    if (!data.author.isEmpty())
        credit << QStringLiteral("by <b style='color:%1'>%2</b>")
                      .arg(fg, data.author.toHtmlEscaped());
    if (!data.head.isEmpty() && !data.base.isEmpty())
        credit << QString::fromUtf8("<span style='font-family:monospace;'>%1"
                                    "</span> \xE2\x86\x92 <span style='font-family:"
                                    "monospace;'>%2</span>")
                      .arg(data.head.toHtmlEscaped(), data.base.toHtmlEscaped());
    if (data.openedSecs > 0)
        credit << formatIssueRelativeTime(data.openedSecs * 1000);
    const QString churn =
        mergeChurnHtml(data.files, data.additions, data.deletions);
    if (!churn.isEmpty())
        credit << churn;
    return certificateCardHtml(
        QStringLiteral("Pull request certificate"),
        QStringLiteral("PULL REQUEST OPENED"), data.avatar,
        QStringLiteral("&#10003; Pull request #%1 opened!").arg(data.number),
        data.title.toHtmlEscaped(), credit.join(QString::fromUtf8(" \xC2\xB7 ")),
        mergeVelocityHtml(data.velocity,
                          QStringLiteral("PULL REQUEST VELOCITY"),
                          true),
        QStringLiteral("100%"));
}

QString mergeCelebrationHtml(const MergeCelebrationRow &landed,
                                    const QString &base,
                                    const QList<MergeCelebrationRow> &recent,
                                    int commits, int truncated,
                                    const QList<MergeActorTally> &tallies,
                                    int range,
                                    const MergeVelocity &velocity,
                                    const QVector<int> &activity,
                                    int activityNowSlot,
                                    bool lookBack)
{
    const QString muted = Theme::hex(Theme::Role::FgMuted);
    const QString link = Theme::hex(Theme::Role::AccentFg);
    const QString escapedBase = base.toHtmlEscaped();

    QStringList sections = mergeCertificateHtml(
        landed, base, commits, velocity, tallies,
        (lookBack ? QStringLiteral("MERGED PER AGENT &#183; %1")
                  : QStringLiteral("MORE THAN ONE &#183; %1"))
            .arg(mergeRangeHeading(range)),
        /*alreadyLanded=*/lookBack);
    if (!activity.isEmpty())
        sections << userActivityHeatHtml(activity, activityNowSlot);
    QString html = recent.isEmpty()
                       ? mergeRangeHeaderHtml(QString(), range)
                       : mergeDayRowsHtml(recent, base, truncated, range);

    QStringList ways;
    if (!base.isEmpty())
        ways << QStringLiteral("go back to <a href='fmbranch:%1' "
                               "style='color:%2'>%3</a>")
                    .arg(QString::fromLatin1(QUrl::toPercentEncoding(base)), link,
                         escapedBase);
    if (!landed.mergeCommit.isEmpty())
        ways << QStringLiteral("<a href='fmcommit:%1' style='color:%2'>open the "
                               "merge commit</a>")
                    .arg(landed.mergeCommit, link);
    html += QStringLiteral("<p style='color:%1;margin-top:14px;'>Pick a branch in "
                           "the list to see its changes%2.</p>")
                .arg(muted,
                     ways.isEmpty()
                         ? QString()
                         : QStringLiteral(", ") +
                               ways.join(QStringLiteral(", or ")));
    sections << certificateColumnHtml(html);
    return mergePaneHtml(sections);
}

QString branchNoChangesHtml(const QString &message,
                                   const MergeCelebrationRow &landed,
                                   const QString &base,
                                   const QList<MergeCelebrationRow> &recent,
                                   int truncated,
                                   const QList<MergeActorTally> &tallies,
                                   int range,
                                   const MergeVelocity &velocity)
{
    const QString muted = Theme::hex(Theme::Role::FgMuted);

    QStringList sections;
    const QString lead = certificateColumnHtml(
        QStringLiteral("<p style='color:%1;'>%2</p>")
            .arg(muted, message.toHtmlEscaped()));

    if (!landed.mergeCommit.isEmpty()) {
        sections = mergeCertificateHtml(
            landed, base, /*commits=*/-1, velocity, tallies,
            QStringLiteral("MERGED PER AGENT &#183; %1")
                .arg(mergeRangeHeading(range)),
            /*alreadyLanded=*/true);
        sections.first().prepend(lead);
    } else {
        // With no merge to certify, the page remains a range summary.
        const QString leaderboard = mergeActorTalliesHtml(
            tallies, QStringLiteral("MERGED PER AGENT &#183; %1")
                         .arg(mergeRangeHeading(range)));
        sections << lead
                 << (leaderboard.isEmpty() ? QString()
                                           : certificateColumnHtml(leaderboard))
                 << certificateColumnHtml(mergeVelocityHtml(velocity));
    }
    QString html = mergeDayRowsHtml(recent, base, truncated, range);
    if (recent.isEmpty()) {
        // An empty window still carries the picker: without it there is no way
        // back out of a quiet 24 hours into the week that holds the work.
        html += mergeRangeHeaderHtml(QString(), range);
        html += QStringLiteral("<p style='color:%1;'>Nothing has been merged "
                               "into %2 %3.</p>")
                    .arg(muted, base.toHtmlEscaped(), mergeRangePhrase(range));
    }
    sections << certificateColumnHtml(html);
    return mergePaneHtml(sections);
}

void appendWorkerProcessOutput(QByteArray *output,
                                      const QByteArray &chunk,
                                      qsizetype maxBytes)
{
    if (!output || chunk.isEmpty())
        return;
    output->append(chunk);
    if (maxBytes >= 0 && output->size() > maxBytes)
        *output = output->right(maxBytes);
}

QString workerProcessOutcome(const WorkerProcessResult &result)
{
    if (result.cancelled)
        return QStringLiteral("cancelled");
    if (result.timedOut)
        return QStringLiteral("timed out");
    if (result.ok)
        return QStringLiteral("succeeded");
    if (!result.started)
        return QStringLiteral("failed to start");
    if (result.exitStatus != QProcess::NormalExit)
        return QStringLiteral("crashed");
    return QStringLiteral("failed (exit %1)").arg(result.exitCode);
}

WorkerProcessResult runWorkerProcess(
    const WorkerProcessRequest &request,
    const std::shared_ptr<std::atomic_bool> &cancelled,
    const forkmesh::LogSource &source)
{
    WorkerProcessResult result;
    if (cancelled && cancelled->load(std::memory_order_relaxed)) {
        result.cancelled = true;
        return result;
    }

    quint64 activityId = 0;
    if (!request.activityKind.isEmpty()) {
        forkmesh::BackgroundWork work;
        work.kind = request.activityKind;
        work.detail = request.activityDetail;
        work.execution = forkmesh::ActionTelemetry::Execution::Worker;
        work.source = source;
        work.routine = request.activityRoutine;
        work.workingDirectory = request.workingDirectory;
        work.queuedMs = request.activityQueuedMs;
        activityId = forkmesh::BackgroundActivity::begin(std::move(work));
    }
    QProcess process;
    if (!request.workingDirectory.isEmpty())
        process.setWorkingDirectory(request.workingDirectory);
    if (!request.environment.isEmpty())
        process.setProcessEnvironment(request.environment);
    process.setProcessChannelMode(request.channelMode);

    QElapsedTimer elapsed;
    elapsed.start();
    process.start(request.program, request.arguments);
    process.closeWriteChannel();

    const auto drain = [&] {
        appendWorkerProcessOutput(&result.output,
                                  process.readAllStandardOutput(),
                                  request.maxOutputBytes);
        if (request.channelMode != QProcess::MergedChannels)
            process.readAllStandardError(); // never let an ignored pipe grow
    };
    const auto stop = [&] {
        forkmesh::stopProcessGracefully(process);
        drain();
    };

    while (process.state() != QProcess::NotRunning) {
        if (cancelled && cancelled->load(std::memory_order_relaxed)) {
            result.cancelled = true;
            stop();
            break;
        }
        if (request.timeoutMs > 0 && elapsed.hasExpired(request.timeoutMs)) {
            result.timedOut = true;
            stop();
            break;
        }
        const int remaining =
            request.timeoutMs > 0
                ? qMax(1, request.timeoutMs - int(elapsed.elapsed()))
                : 50;
        process.waitForFinished(qMin(50, remaining));
        drain();
    }
    drain();

    result.started = process.error() != QProcess::FailedToStart;
    result.exitCode = process.exitCode();
    result.exitStatus = process.exitStatus();
    result.ok = result.started && !result.timedOut && !result.cancelled &&
                result.exitStatus == QProcess::NormalExit &&
                result.exitCode == 0;
    if (activityId != 0) {
        const QString answer =
            result.started && !result.timedOut && !result.cancelled &&
                    result.exitStatus == QProcess::NormalExit
                ? forkmesh::gitProbeAnswerOutcome(request.program,
                                                  request.arguments,
                                                  result.exitCode)
                : QString();
        forkmesh::BackgroundActivity::end(
            activityId, answer.isEmpty() ? workerProcessOutcome(result) : answer);
    }
    return result;
}

QString gitProcessWorkingDirectory(const QProcess &process)
{
    if (!process.workingDirectory().isEmpty())
        return process.workingDirectory();
    const QStringList args = process.arguments();
    const int at = args.indexOf(QStringLiteral("-C"));
    if (at >= 0 && at + 1 < args.size())
        return args.at(at + 1);
    return QString();
}

QString processExitOutcome(const QProcess &process)
{
    if (process.error() == QProcess::FailedToStart)
        return QStringLiteral("failed to start");
    if (process.state() != QProcess::NotRunning)
        return QStringLiteral("still running");
    if (process.exitStatus() != QProcess::NormalExit)
        return QStringLiteral("crashed");
    if (process.exitCode() == 0)
        return QStringLiteral("succeeded");
    const QString answer = forkmesh::gitProbeAnswerOutcome(
        process.program(), process.arguments(), process.exitCode());
    if (!answer.isEmpty())
        return answer;
    return QStringLiteral("failed (exit %1)").arg(process.exitCode());
}

bool waitForGit(QProcess &process, QString *err,
                       const forkmesh::LogSource &source)
{
    const QCoreApplication *app = QCoreApplication::instance();
    const bool onGuiThread = app && QThread::currentThread() == app->thread();

    // Announce the wait to the footer's background strip. This is
    // the one chokepoint every git subprocess passes through, on the GUI thread
    // and off it, so a single ticket here is what makes "git" appear while a
    // slow fetch/clone/log runs. Fast reads never reach the strip's show delay,
    // so the hot path pays only an atomic increment. Being the one chokepoint
    // is also why the ticket carries the caller's captured source rather than
    // this function's: these three lines are where every git read in the app
    // waits, so blaming them says nothing about which flow is spinning.
    // The ticket also says which checkout the read ran in and how the process
    // actually exited (adhoc #186): the routine that asked is whatever
    // BackgroundRoutine is current on this thread, which runGitCapture carries
    // across to its worker.
    forkmesh::BackgroundWork gitWork;
    gitWork.kind = QStringLiteral("git");
    gitWork.detail = gitProcessCommandLine(process);
    // GUI-thread Git waits below are cooperative: every short polling slice
    // returns to Qt's event dispatcher, including user input and painting.
    // Calling these UiBlocking made a responsive multi-read overview look the
    // same as code that genuinely freezes the window and flooded BGBLOCK with
    // even 7 ms stage/restore commands. Keep worker reads distinct, and record
    // the pumped GUI path as UI-deferred so BGBLOCK remains an actionable list
    // of real event-loop stalls.
    gitWork.execution = onGuiThread
                            ? forkmesh::ActionTelemetry::Execution::UiDeferred
                            : forkmesh::ActionTelemetry::Execution::Worker;
    gitWork.source = source;
    gitWork.workingDirectory = gitProcessWorkingDirectory(process);
    struct GitWaitTicket {
        quint64 id;
        const QProcess &process;
        bool timedOut = false;
        ~GitWaitTicket()
        {
            forkmesh::BackgroundActivity::end(
                id, timedOut ? QStringLiteral("timed out")
                             : processExitOutcome(process));
        }
    } gitActivity{forkmesh::BackgroundActivity::begin(std::move(gitWork)),
                  process};

    std::optional<BlockingCallScope> crumb;
    if (onGuiThread)
        crumb.emplace(gitBlockingCrumb(process));

    const int timeoutMs = forkmesh::gitTimeoutMsForArgs(
        process.arguments(), gitWaitTimeoutMs(process.arguments()));
    if (!onGuiThread) {
        if (process.waitForFinished(timeoutMs))
            return true;
        gitActivity.timedOut = true;
        const QString message = gitTimeoutError(process, timeoutMs);
        if (err)
            *err = message;
        return false;
    }
    if (keepAliveClock().elapsed() - g_lastKeepAlivePumpMs >= 100)
        pumpKeepAlive();
    QElapsedTimer timer;
    timer.start();
    while (!process.waitForFinished(40)) {
        if (process.state() == QProcess::NotRunning)
            return true; // exited between polls; caller inspects the exit code
        if (timer.hasExpired(timeoutMs)) {
            gitActivity.timedOut = true;
            const QString message = gitTimeoutError(process, timeoutMs);
            if (err)
                *err = message;
            return false;
        }
        pumpKeepAlive();
    }
    return true;
}

void trackProcessActivity(QProcess *process, const QString &kind,
                                 const QString &detail,
                                 const forkmesh::LogSource &source)
{
    if (!process)
        return;
    forkmesh::BackgroundWork work;
    work.kind = kind;
    work.detail = detail;
    work.execution = forkmesh::ActionTelemetry::Execution::Async;
    work.source = source;
    work.workingDirectory = process->workingDirectory();
    const quint64 id = forkmesh::BackgroundActivity::begin(std::move(work));
    auto retired = std::make_shared<bool>(false);
    auto retire = [id, retired](const QString &outcome) {
        if (*retired)
            return;
        *retired = true;
        forkmesh::BackgroundActivity::end(id, outcome);
    };
    QObject::connect(process, &QProcess::finished, process,
                     [retire](int code, QProcess::ExitStatus status) {
                         retire(status != QProcess::NormalExit
                                    ? QStringLiteral("crashed")
                                : code == 0
                                    ? QStringLiteral("succeeded")
                                    : QStringLiteral("failed (exit %1)")
                                          .arg(code));
                     });
    QObject::connect(process, &QObject::destroyed, process,
                     [retire](QObject *) {
                         retire(QStringLiteral("cancelled"));
                     });
}

